import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { describe, expect, it } from 'vitest';
import { loadKeywordRules } from '../../src/config.js';
import { classifyState } from '../../src/generator/extract.js';

const rules = loadKeywordRules(
  join(dirname(fileURLToPath(import.meta.url)), '../../config/keywords.yaml'),
);

const SAMPLES: readonly { text: string; expected: 'done' | 'doing' | 'plan' | 'blocked' }[] = [
  { text: '已完成鉴权模块并合入主分支', expected: 'done' },
  { text: '修复分页越界缺陷', expected: 'done' },
  { text: '实现数据导出能力', expected: 'doing' },
  { text: '发布候选版本并通过验收', expected: 'done' },
  { text: '联调支付回调链路', expected: 'doing' },
  { text: '排查生产环境告警', expected: 'doing' },
  { text: '推进合同审批流', expected: 'doing' },
  { text: '明日准备需求评审材料', expected: 'plan' },
  { text: '待办：补齐接口文档', expected: 'plan' },
  { text: '阻塞：等待第三方字段确认', expected: 'blocked' },
  { text: '卡住，依赖运维开通白名单', expected: 'blocked' },
  { text: '整理当日会议纪要', expected: 'doing' },
  { text: '调研竞品方案', expected: 'plan' },
  { text: '重构采集模块结构', expected: 'doing' },
  { text: '评审合并请求意见汇总', expected: 'doing' },
];

describe('T-011 关键词规则库与状态判定', () => {
  it('人工标注样本准确率 ≥ 90%', () => {
    const hit = SAMPLES.filter((s) => classifyState(s.text, rules).state === s.expected);
    expect(hit.length / SAMPLES.length).toBeGreaterThanOrEqual(0.9);
  });

  it('无命中返回 doing 且置信度为 0', () => {
    expect(classifyState('整理当日会议纪要', rules)).toEqual({ state: 'doing', confidence: 0 });
    expect(classifyState('   ', rules)).toEqual({ state: 'doing', confidence: 0 });
  });

  it('多规则命中按权重取最高分', () => {
    const result = classifyState('已完成鉴权模块并合入主分支', rules);
    expect(result.state).toBe('done');
    expect(result.confidence).toBeGreaterThan(0);
    expect(result.confidence).toBeLessThanOrEqual(1);
  });
});

import { describe, expect, it } from 'vitest';
import { FixedClock } from '../../src/clock.js';
import type { WorkBlock } from '../../src/config.js';
import { ERROR_CODES, SdrError } from '../../src/errors.js';
import { assignBlocks } from '../../src/generator/timeline.js';
import type { Event } from '../../src/types.js';

const clock = new FixedClock(new Date('2026-11-25T12:00:00+08:00'));

const BLOCKS: readonly WorkBlock[] = [
  { name: 'morning', start: '09:00', end: '12:00' },
  { name: 'afternoon', start: '13:30', end: '18:00' },
  { name: 'evening', start: '19:00', end: '22:00' },
];

function ev(id: string, at: string): Event {
  return {
    memberId: 1,
    source: 'github',
    sourceId: id,
    kind: 'commit',
    occurredAt: new Date(at),
    title: `feat: ${id}`,
    dedupeKey: `dk-${id}`,
    isPrimary: true,
    runId: 'run-1',
  };
}

function blockFor(at: string): string | undefined {
  const map = assignBlocks([ev('x', at)], BLOCKS, clock);
  for (const [name, list] of map) {
    if (list.length > 0) return name;
  }
  return undefined;
}

describe('T-012 时段划分', () => {
  it('落在休息区间的事件归入前一工作时段（IR-05）', () => {
    expect(blockFor('2026-11-25T12:30:00+08:00')).toBe('morning');
    expect(blockFor('2026-11-25T13:00:00+08:00')).toBe('morning');
    expect(blockFor('2026-11-25T18:30:00+08:00')).toBe('afternoon');
  });

  it('左闭右开，仅按开始时间归位一次', () => {
    expect(blockFor('2026-11-25T09:00:00+08:00')).toBe('morning');
    expect(blockFor('2026-11-25T12:00:00+08:00')).toBe('morning');
    expect(blockFor('2026-11-25T13:30:00+08:00')).toBe('afternoon');
    const map = assignBlocks([ev('a', '2026-11-25T11:59:00+08:00')], BLOCKS, clock);
    const total = [...map.values()].reduce((n, xs) => n + xs.length, 0);
    expect(total).toBe(1);
  });

  it('早于首段归首段，晚于末段归末段', () => {
    expect(blockFor('2026-11-25T07:30:00+08:00')).toBe('morning');
    expect(blockFor('2026-11-25T23:10:00+08:00')).toBe('evening');
  });

  it('时刻按 clock.timeZone 解释', () => {
    expect(blockFor('2026-11-25T04:30:00Z')).toBe('morning');
  });

  it('时段重叠或乱序抛 SDR-E301', () => {
    const overlap: WorkBlock[] = [
      { name: 'a', start: '09:00', end: '12:00' },
      { name: 'b', start: '11:00', end: '13:00' },
    ];
    expect(() => assignBlocks([], overlap, clock)).toThrow(SdrError);
    try {
      assignBlocks([], overlap, clock);
    } catch (error) {
      expect((error as SdrError).code).toBe(ERROR_CODES.WORK_BLOCKS_INVALID);
    }
  });

  it('同段事件按发生时间升序', () => {
    const map = assignBlocks(
      [ev('late', '2026-11-25T10:30:00+08:00'), ev('early', '2026-11-25T09:10:00+08:00')],
      BLOCKS,
      clock,
    );
    expect(map.get('morning')?.map((e) => e.sourceId)).toEqual(['early', 'late']);
  });
});

import { describe, expect, it } from 'vitest';
import {
  resolveAttribution,
  type AttributionContext,
} from '../../src/generator/attribution.js';
import type { Event } from '../../src/types.js';

function commit(detail?: string, payload?: unknown): Event {
  return {
    memberId: 1,
    source: 'github',
    sourceId: 'sha-1',
    kind: 'commit',
    occurredAt: new Date('2026-11-25T10:00:00+08:00'),
    title: 'feat: 协作能力',
    ...(detail === undefined ? {} : { detail }),
    ...(payload === undefined ? {} : { payload }),
    dedupeKey: 'dk-1',
    isPrimary: true,
    runId: 'run-1',
  };
}

function ctx(
  lookup: (key: string) => number | undefined,
  taskMembers: readonly number[] = [],
): AttributionContext {
  return {
    findMemberByGithubLogin: lookup,
    findMemberByEmailOrName: lookup,
    taskWindowMembers: () => taskMembers,
  };
}

describe('T-013 协作归属三级策略', () => {
  it('Co-authored-by 返回全部作者（CS-03）', () => {
    const event = commit(
      ['Co-authored-by: bob <bob@example.com>', 'Co-authored-by: carol <carol@example.com>'].join(
        '\n',
      ),
    );
    const directory: Record<string, number> = {
      bob: 2,
      'bob@example.com': 2,
      carol: 3,
      'carol@example.com': 3,
    };
    const result = resolveAttribution(event, ctx((k) => directory[k]));
    expect(result.kind).toBe('coauthor');
    expect(result.confirmed).toBe(true);
    expect(result.members).toEqual([
      { memberId: 1, role: 'primary' },
      { memberId: 2, role: 'co' },
      { memberId: 3, role: 'co' },
    ]);
  });

  it('仅标注提交作者时不扩增归属', () => {
    const event = commit('Co-authored-by: alice <alice@example.com>');
    const result = resolveAttribution(
      event,
      ctx((k) => (k === 'alice@example.com' || k === 'alice' ? 1 : undefined)),
    );
    expect(result.kind).toBe('fallback');
    expect(result.members).toEqual([{ memberId: 1, role: 'primary' }]);
  });

  it('任务时间窗 → task_window', () => {
    const result = resolveAttribution(commit(), ctx(() => undefined, [1, 4]));
    expect(result.kind).toBe('task_window');
    expect(result.confirmed).toBe(true);
    expect(result.members).toEqual([
      { memberId: 1, role: 'primary' },
      { memberId: 4, role: 'co' },
    ]);
  });

  it('无法判定 → fallback 待确认', () => {
    expect(resolveAttribution(commit(), ctx(() => undefined))).toEqual({
      kind: 'fallback',
      confirmed: false,
      members: [{ memberId: 1, role: 'primary' }],
    });
  });

  it('非 commit 按源作者归属', () => {
    const event: Event = { ...commit(), kind: 'task_done', source: 'feishu' };
    expect(resolveAttribution(event, ctx(() => undefined))).toEqual({
      kind: 'author',
      confirmed: true,
      members: [{ memberId: 1, role: 'primary' }],
    });
  });

  it('禁止仅以 event.memberId 充当多人归属', () => {
    const result = resolveAttribution(commit(), ctx(() => undefined));
    expect(result.members).toHaveLength(1);
    expect(result.members[0]?.memberId).toBe(1);
  });
});

import { describe, expect, it } from 'vitest';
import { ERROR_CODES, SdrError } from '../../src/errors.js';
import { renderEntry } from '../../src/generator/render.js';
import type { Entry, EntryState, LinkType, SourceLink } from '../../src/types.js';

const STATES: readonly EntryState[] = ['done', 'doing', 'plan', 'blocked'];
const LINK_TYPES: readonly LinkType[] = ['url', 'path', 'note'];

function baseEntry(overrides: Partial<Entry> = {}): Entry {
  return {
    reportId: 1,
    timeBlock: 'morning',
    state: 'done',
    content: '完成鉴权接口',
    orderIndex: 0,
    isManual: false,
    attributionKind: 'author',
    attributionConfirmed: true,
    members: [{ entryId: 1, memberId: 1, role: 'primary' }],
    ...overrides,
  };
}

function linkOf(linkType: LinkType, target: string): SourceLink {
  return { entryId: 1, linkType, target };
}

describe('T-014 去人称渲染', () => {
  it('多种状态与链接形态不含第一人称（CS-05）', () => {
    for (const state of STATES) {
      for (const linkType of LINK_TYPES) {
        const target = linkType === 'note' ? '飞书任务备注' : `https://example.com/${linkType}`;
        const content = `${state} 状态条目描述`;
        const text = renderEntry(baseEntry({ content, state }), [linkOf(linkType, target)]);
        expect(text).not.toMatch(/我|我们|咱/);
        if (linkType === 'note') {
          expect(text).toContain(`来源：${target}`);
        } else {
          expect(text).toContain(target);
        }
      }
    }
  });

  it('正文超过 60 字截断', () => {
    const long = '推进'.repeat(40);
    const text = renderEntry(baseEntry({ content: long }), [linkOf('url', 'https://example.com/x')]);
    const bodyEnd = text.indexOf('（');
    const body = bodyEnd < 0 ? text : text.slice(0, bodyEnd);
    expect(body.length).toBeLessThanOrEqual(60);
    expect(body.endsWith('…')).toBe(true);
  });

  it('待确认、协作、跨天前缀按契约拼接', () => {
    const text = renderEntry(
      baseEntry({
        attributionConfirmed: false,
        originalDate: '2026-11-24',
        content: '完成联调',
        members: [
          { entryId: 1, memberId: 1, role: 'primary' },
          { entryId: 1, memberId: 2, role: 'co' },
        ],
      }),
      [linkOf('note', '飞书沟通')],
    );
    expect(text).toBe('[待确认] （自 11-24 起）完成联调（协作）（来源：飞书沟通）');
  });

  it('无来源链接抛 SDR-E601', () => {
    expect(() => renderEntry(baseEntry(), [])).toThrow(SdrError);
    try {
      renderEntry(baseEntry(), []);
    } catch (error) {
      expect((error as SdrError).code).toBe(ERROR_CODES.SOURCE_LINK_MISSING);
    }
  });

  it('url 与 path 形态快照', () => {
    expect(
      renderEntry(baseEntry(), [linkOf('url', 'https://github.com/acme/app/commit/a1')]),
    ).toBe('完成鉴权接口（https://github.com/acme/app/commit/a1）');
    expect(
      renderEntry(baseEntry({ content: '修复分页' }), [linkOf('path', '/repo/src/a.ts')]),
    ).toBe('修复分页（/repo/src/a.ts）');
  });
});

import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { describe, expect, it } from 'vitest';
import { FixedClock } from '../../src/clock.js';
import { loadKeywordRules, loadWorkBlocks } from '../../src/config.js';
import type { AttributionContext } from '../../src/generator/attribution.js';
import { renderEntry } from '../../src/generator/render.js';
import { assembleReport, renderReportBody } from '../../src/generator/report.js';
import { openDatabase } from '../../src/store/db.js';
import { createRepo, type SaveReportBundleEntry } from '../../src/store/repo.js';
import type { Event, ReportStatus } from '../../src/types.js';

const CONFIG = join(dirname(fileURLToPath(import.meta.url)), '../../config');
const clock = new FixedClock(new Date('2026-11-25T18:00:00+08:00'));
const rules = loadKeywordRules(join(CONFIG, 'keywords.yaml'));
const blocks = loadWorkBlocks(join(CONFIG, 'work-hours.yaml'));

const attributionCtx: AttributionContext = {
  findMemberByGithubLogin: () => undefined,
  findMemberByEmailOrName: () => undefined,
  taskWindowMembers: () => [],
};

function setupRepo() {
  const db = openDatabase(':memory:');
  const repo = createRepo(db, clock);
  repo.insertMember({ githubLogin: 'alice', displayName: 'Alice', active: true });
  return { db, repo };
}

function ghEvent(overrides: Partial<Event> = {}): Event {
  return {
    memberId: 1,
    source: 'github',
    sourceId: 'sha-1',
    kind: 'commit',
    occurredAt: new Date('2026-11-25T09:30:00+08:00'),
    title: '完成鉴权接口',
    dedupeKey: 'dk-1',
    isPrimary: true,
    runId: 'run-1',
    payload: { html_url: 'https://github.com/acme/app/commit/sha-1' },
    ...overrides,
  };
}

function loadBundle(db: ReturnType<typeof openDatabase>, reportId: number) {
  const report = db
    .prepare(`SELECT * FROM report WHERE id = ?`)
    .get(reportId) as {
    id: number;
    status: ReportStatus;
    body: string | null;
  };
  const entries = db
    .prepare(`SELECT * FROM entry WHERE report_id = ? ORDER BY order_index`)
    .all(reportId) as Array<{
    id: number;
    time_block: string;
    state: string;
    content: string;
    order_index: number;
    original_date: string | null;
    attribution_kind: string;
    attribution_confirmed: number;
  }>;
  const links = db
    .prepare(
      `SELECT sl.* FROM source_link sl
       JOIN entry e ON e.id = sl.entry_id WHERE e.report_id = ?`,
    )
    .all(reportId) as Array<{ entry_id: number; link_type: string; target: string }>;
  return { report, entries, links };
}

describe('T-015 日报装配与状态机', () => {
  it('有事件时生成 draft，正文与渲染一致', () => {
    const { db, repo } = setupRepo();
    const result = assembleReport({
      repo,
      clock,
      memberId: 1,
      reportDate: '2026-11-25',
      events: [
        ghEvent(),
        ghEvent({
          dedupeKey: 'dk-2',
          sourceId: 'sha-2',
          occurredAt: new Date('2026-11-25T14:00:00+08:00'),
          title: '修复分页越界',
          payload: { html_url: 'https://github.com/acme/app/commit/sha-2' },
        }),
      ],
      rules,
      blocks,
      attributionCtx,
    });
    expect(result.status).toBe('draft');
    expect(result.skipped).toBe(false);
    const bundle = loadBundle(db, result.reportId);
    expect(bundle.entries.map((e) => e.time_block)).toEqual(['morning', 'afternoon']);
    const lines = bundle.entries.map((e) => {
      const entryLinks = linksFor(bundle.links, e.id);
      return renderEntry(
        {
          reportId: result.reportId,
          timeBlock: e.time_block,
          state: e.state as SaveReportBundleEntry['state'],
          content: e.content,
          orderIndex: e.order_index,
          isManual: false,
          attributionKind: e.attribution_kind as SaveReportBundleEntry['attributionKind'],
          attributionConfirmed: e.attribution_confirmed === 1,
          members: [{ entryId: e.id, memberId: 1, role: 'primary' }],
        },
        entryLinks,
      );
    });
    expect(bundle.report.body).toBe(lines.join('\n'));
  });

  it('请假生成占位条目（CS-06）', () => {
    const { db, repo } = setupRepo();
    const result = assembleReport({
      repo,
      clock,
      memberId: 1,
      reportDate: '2026-11-25',
      events: [],
      rules,
      blocks,
      attributionCtx,
      leave: true,
    });
    const bundle = loadBundle(db, result.reportId);
    expect(bundle.report.status).toBe('leave');
    expect(bundle.entries).toHaveLength(1);
    expect(bundle.entries[0]?.content).toBe('请假（未出勤）');
  });

  it('无事件生成空白模板（CS-14）', () => {
    const { db, repo } = setupRepo();
    const result = assembleReport({
      repo,
      clock,
      memberId: 1,
      reportDate: '2026-11-25',
      events: [],
      rules,
      blocks,
      attributionCtx,
    });
    const bundle = loadBundle(db, result.reportId);
    expect(result.status).toBe('blank');
    expect(bundle.report.status).toBe('blank');
    expect(bundle.entries[0]?.content).toBe('今日无进展记录');
  });

  it('跨天任务写入 original_date（CS-16）', () => {
    const { db, repo } = setupRepo();
    const createdAt = Date.parse('2026-11-23T10:00:00+08:00');
    const result = assembleReport({
      repo,
      clock,
      memberId: 1,
      reportDate: '2026-11-25',
      events: [
        ghEvent({
          source: 'feishu',
          kind: 'task_done',
          sourceId: 't1',
          dedupeKey: 'dk-t1',
          title: '完成跨天任务',
          payload: { state: 'done', created_at: String(createdAt) },
        }),
      ],
      rules,
      blocks,
      attributionCtx,
    });
    const bundle = loadBundle(db, result.reportId);
    expect(bundle.entries[0]?.original_date).toBe('2026-11-23');
    expect(bundle.report.body).toContain('（自 11-23 起）');
  });

  it('已确认日报不被覆盖，除非 force', () => {
    const { db, repo } = setupRepo();
    const first = assembleReport({
      repo,
      clock,
      memberId: 1,
      reportDate: '2026-11-25',
      events: [ghEvent()],
      rules,
      blocks,
      attributionCtx,
    });
    db.prepare(`UPDATE report SET status = 'confirmed' WHERE id = ?`).run(first.reportId);

    const skipped = assembleReport({
      repo,
      clock,
      memberId: 1,
      reportDate: '2026-11-25',
      events: [ghEvent({ title: '不应写入' })],
      rules,
      blocks,
      attributionCtx,
    });
    expect(skipped.skipped).toBe(true);
    expect(loadBundle(db, first.reportId).entries[0]?.content).toBe('完成鉴权接口');

    const forced = assembleReport({
      repo,
      clock,
      memberId: 1,
      reportDate: '2026-11-25',
      events: [ghEvent({ title: '强制重生', dedupeKey: 'dk-force' })],
      rules,
      blocks,
      attributionCtx,
      force: true,
    });
    expect(forced.skipped).toBe(false);
    expect(loadBundle(db, forced.reportId).entries[0]?.content).toBe('强制重生');
    const count = (
      db
        .prepare(`SELECT COUNT(*) AS n FROM report WHERE member_id = 1 AND report_date = ?`)
        .get('2026-11-25') as { n: number }
    ).n;
    expect(count).toBe(1);
  });
});

function linksFor(
  rows: Array<{ entry_id: number; link_type: string; target: string }>,
  entryId: number,
) {
  return rows
    .filter((r) => r.entry_id === entryId)
    .map((r) => ({
      entryId,
      linkType: r.link_type as 'url' | 'path' | 'note',
      target: r.target,
    }));
}

describe('renderReportBody', () => {
  it('多行正文与逐条渲染一致', () => {
    const drafts: SaveReportBundleEntry[] = [
      {
        timeBlock: 'morning',
        state: 'done',
        content: '条目一',
        orderIndex: 0,
        isManual: false,
        attributionKind: 'author',
        attributionConfirmed: true,
        members: [{ memberId: 1, role: 'primary' }],
        links: [{ linkType: 'note', target: '说明' }],
      },
    ];
    expect(renderReportBody(drafts)).toContain('条目一');
  });
});

import { describe, expect, it } from 'vitest';
import { FixedClock } from '../../src/clock.js';
import { renderSummary } from '../../src/generator/summary.js';
import { openDatabase } from '../../src/store/db.js';
import { SUMMARY_ROWS_SQL, createRepo, type SaveReportBundleInput } from '../../src/store/repo.js';

const clock = new FixedClock(new Date('2026-11-25T18:00:00+08:00'));
const DATE = '2026-11-25';

function entry(
  content: string,
  state: SaveReportBundleInput['entries'][number]['state'],
  orderIndex = 0,
): SaveReportBundleInput['entries'][number] {
  return {
    timeBlock: 'morning',
    state,
    content,
    orderIndex,
    isManual: false,
    attributionKind: 'author',
    attributionConfirmed: true,
    members: [{ memberId: 1, role: 'primary' }],
    links: [{ linkType: 'note', target: '来源说明' }],
  };
}

function seedRepo() {
  const db = openDatabase(':memory:');
  const repo = createRepo(db, clock);
  const insert = db.prepare(
    `INSERT INTO member (id, github_login, display_name, active, created_at) VALUES (?, ?, ?, 1, ?)`,
  );
  const ts = clock.now().toISOString();
  for (const [id, login, name] of [
    [1, 'alice', 'Alice'],
    [2, 'bob', 'Bob'],
    [3, 'carol', 'Carol'],
    [4, 'dave', 'Dave'],
    [5, 'eve', 'Eve'],
  ] as const) {
    insert.run(id, login, name, ts);
  }

  const save = (
    memberId: number,
    status: SaveReportBundleInput['report']['status'],
    entries: SaveReportBundleInput['entries'],
  ) => {
    repo.saveReportBundle({
      report: { memberId, reportDate: DATE, status, generatedAt: clock.now() },
      entries,
    });
  };

  save(1, 'draft', [
    entry('完成登录', 'done', 0),
    entry('修复分页', 'done', 1),
    entry('联调支付', 'doing', 2),
  ]);
  save(2, 'confirmed', [entry('阻塞：等待接口', 'blocked', 0)]);
  save(3, 'blank', [entry('今日无进展记录', 'doing', 0)]);
  save(4, 'leave', [entry('请假（未出勤）', 'plan', 0)]);
  return repo;
