import type { KeywordRule } from '../config.js';
import type { EntryState } from '../types.js';

export type { KeywordRule } from '../config.js';

export interface Classification {
  readonly state: EntryState;
  readonly confidence: number;
}

const STATE_ORDER: readonly EntryState[] = ['done', 'doing', 'plan', 'blocked'];

/** 关键词状态判定：按权重取最高分；无命中返回 doing / confidence 0。 */
export function classifyState(text: string, rules: readonly KeywordRule[]): Classification {
  const trimmed = text.trim();
  if (trimmed === '') return { state: 'doing', confidence: 0 };

  const scores = new Map<EntryState, number>();
  let total = 0;
  for (const rule of rules) {
    if (!rule.pattern.test(trimmed)) continue;
    scores.set(rule.state, (scores.get(rule.state) ?? 0) + rule.weight);
    total += rule.weight;
  }
  if (total === 0) return { state: 'doing', confidence: 0 };

  let best: EntryState = 'doing';
  let bestScore = 0;
  for (const state of STATE_ORDER) {
    const score = scores.get(state) ?? 0;
    if (score > bestScore) {
      bestScore = score;
      best = state;
    }
  }
  return { state: best, confidence: Math.round((bestScore / total) * 100) / 100 };
}

import { minutesOfDay } from '../clock.js';
import type { WorkBlock } from '../config.js';
import { ERROR_CODES, SdrError } from '../errors.js';
import type { Clock, Event } from '../types.js';

export type { WorkBlock } from '../config.js';

function toMinutes(time: string): number {
  const [h = '0', m = '0'] = time.split(':');
  return Number(h) * 60 + Number(m);
}

function validateBlocks(blocks: readonly WorkBlock[]): void {
  if (blocks.length === 0) {
    throw new SdrError(ERROR_CODES.WORK_BLOCKS_INVALID, '时段配置不能为空', { source: 'config' });
  }
  for (let i = 0; i < blocks.length; i += 1) {
    const block = blocks[i]!;
    if (toMinutes(block.start) >= toMinutes(block.end)) {
      throw new SdrError(
        ERROR_CODES.WORK_BLOCKS_INVALID,
        `时段 ${block.name} 的 start 必须早于 end`,
        { source: 'config' },
      );
    }
    const prev = blocks[i - 1];
    if (prev === undefined) continue;
    if (toMinutes(block.start) < toMinutes(prev.start)) {
      throw new SdrError(ERROR_CODES.WORK_BLOCKS_INVALID, `时段 ${block.name} 未按起点升序`, {
        source: 'config',
      });
    }
    if (toMinutes(block.start) < toMinutes(prev.end)) {
      throw new SdrError(
        ERROR_CODES.WORK_BLOCKS_INVALID,
        `时段 ${block.name} 与 ${prev.name} 重叠`,
        { source: 'config' },
      );
    }
  }
}

/** IR-05：休息区间内的事件归入前一工作时段；时刻经 clock.timeZone 解释。 */
export function assignBlocks(
  events: readonly Event[],
  blocks: readonly WorkBlock[],
  clock: Clock,
): Map<string, Event[]> {
  validateBlocks(blocks);
  const buckets = new Map<string, Event[]>();
  for (const block of blocks) buckets.set(block.name, []);

  const sorted = [...events].sort((a, b) => a.occurredAt.getTime() - b.occurredAt.getTime());

  for (const event of sorted) {
    const at = minutesOfDay(clock, event.occurredAt);
    let target = blocks[0]!;
    for (const block of blocks) {
      if (at >= toMinutes(block.start)) target = block;
      if (at >= toMinutes(block.start) && at < toMinutes(block.end)) {
        target = block;
        break;
      }
    }
    buckets.get(target.name)?.push(event);
  }

  return buckets;
}

import type { AttributionKind, Event } from '../types.js';

export interface AttributionResult {
  readonly members: readonly { readonly memberId: number; readonly role: 'primary' | 'co' }[];
  readonly kind: AttributionKind;
  readonly confirmed: boolean;
}

export interface AttributionContext {
  readonly findMemberByGithubLogin: (login: string) => number | undefined;
  readonly findMemberByEmailOrName: (nameOrEmail: string) => number | undefined;
  readonly taskWindowMembers: (event: Event) => readonly number[];
}

const COAUTHOR_LINE = /co-authored-by:\s*(.+)/gi;

function coauthorText(event: Event): string {
  const chunks: string[] = [];
  if (event.detail !== undefined && event.detail !== '') chunks.push(event.detail);
  if (typeof event.payload === 'string') chunks.push(event.payload);
  if (typeof event.payload === 'object' && event.payload !== null) {
    const payload = event.payload as Record<string, unknown>;
    if (typeof payload.body === 'string') chunks.push(payload.body);
    if (typeof payload.message === 'string') chunks.push(payload.message);
  }
  return chunks.join('\n');
}

function resolveCoauthors(event: Event, ctx: AttributionContext): number[] {
  const seen = new Set<number>();
  const text = coauthorText(event);
  for (const match of text.matchAll(COAUTHOR_LINE)) {
    const raw = (match[1] ?? '').trim();
    if (raw === '') continue;
    const email = /<([^>]+)>/.exec(raw)?.[1]?.trim();
    const name = raw.replace(/<[^>]*>/g, '').trim();
    const loginGuess = name.includes('@') ? undefined : name.toLowerCase();
    const candidates = [loginGuess, email, name].filter(
      (v): v is string => v !== undefined && v !== '',
    );
    for (const key of candidates) {
      const id =
        ctx.findMemberByGithubLogin(key) ?? ctx.findMemberByEmailOrName(key.toLowerCase());
      if (id !== undefined && id !== event.memberId) seen.add(id);
    }
  }
  return [...seen];
}

/** 三级归属：Co-authored-by → 任务窗 → fallback；禁止单用 event.memberId 冒充多人。 */
export function resolveAttribution(event: Event, ctx: AttributionContext): AttributionResult {
  const primary = { memberId: event.memberId, role: 'primary' as const };

  if (event.kind !== 'commit') {
    return { members: [primary], kind: 'author', confirmed: true };
  }

  const coauthors = resolveCoauthors(event, ctx);
  if (coauthors.length > 0) {
    return {
      members: [primary, ...coauthors.map((memberId) => ({ memberId, role: 'co' as const }))],
      kind: 'coauthor',
      confirmed: true,
    };
  }

  const others = ctx
    .taskWindowMembers(event)
    .filter((memberId) => memberId !== event.memberId);
  if (others.length > 0) {
    return {
      members: [primary, ...others.map((memberId) => ({ memberId, role: 'co' as const }))],
      kind: 'task_window',
      confirmed: true,
    };
  }

  return { members: [primary], kind: 'fallback', confirmed: false };
}

